{
  "version": 1,
  "comment": "gh-1199 AC6 flake quarantine. A file listed here is REMOVED from every deterministic Quality-gate integration leg (pty-integration-linux shards and the integration-mock leg) until its fix PR lands \u2014 nightly still runs it (supervised), producing the AC4 repeat-run proof for un-quarantine. Granularity is the FILE (dart test cannot exclude a single test inside a file): the `test` field records the offending test name so the issue and the fix PR review know exactly what flaked. Every entry MUST carry: issue (flake tracker issue with the failing runs), since (ISO date), runs (the gate run ids that proved the flake, >=2 distinct SHAs).",
  "quarantined": [
    {
      "file": "test/integration/job_board_stability_pty_test.dart",
      "test": "stacked boards freeze across settles; composer stays reserved at 80/120/200",
      "issue": "https://github.com/IstiN/flutter_agent_harness/issues/1250",
      "since": "2026-10-04",
      "runs": [
        37234343418,
        37219125631,
        37211433024
      ]
    },
    {
      "file": "test/integration/dap_wake_hang_test.dart",
      "test": "mail-wake turns never wedge: 12 hub DMs each wake and answer; ESC recovers a stalled wake",
      "issue": "https://github.com/IstiN/flutter_agent_harness/issues/1248",
      "since": "2026-10-04",
      "runs": [
        37225510196,
        37214807813,
        37214599192
      ]
    },
    {
      "file": "test/integration/scheduled_indicator_test.dart",
      "test": "a scheduled follow-up shows on top of the working row, persists while idle, and clears when it fires",
      "issue": "https://github.com/IstiN/flutter_agent_harness/issues/1252",
      "since": "2026-10-04",
      "runs": [
        37223287603,
        37221386347,
        37221353540
      ]
    },
    {
      "file": "test/integration/dap_cli_e2e_test.dart",
      "test": "E2E-start + E2E-endtoend + IT-stop: start, zero-config extension join, DM round-trip via the persisted credential, status, stop",
      "issue": "https://github.com/IstiN/flutter_agent_harness/issues/1293",
      "since": "2026-10-05",
      "runs": [
        37317512055,
        37257113766
      ]
    }
  ]
}

REQUIRED_FIELDS = ("file", "issue", "since", "runs")


def load_quarantine(path: str = LIST_PATH) -> list:
    with open(path, encoding="utf-8") as f:
        doc = json.load(f)
    entries = doc.get("quarantined")
    if not isinstance(entries, list):
        raise ValueError(f"{path}: 'quarantined' must be a list")
    return entries


def quarantined_files(entries: list) -> set:
    return {e["file"] for e in entries}


def check(path: str = LIST_PATH) -> int:
    """Validate the list; a stale/under-documented entry fails the gate."""
    ok = True
    try:
        entries = load_quarantine(path)
    except (OSError, json.JSONDecodeError, ValueError) as e:
        print(f"::error::{e}", file=sys.stderr)
        return 1
    for e in entries:
        name = e.get("file", "<missing file>")
        for field in REQUIRED_FIELDS:
            if not e.get(field):
                ok = False
                print(f"::error::quarantine entry {name}: missing '{field}' "
                      f"(every entry needs {list(REQUIRED_FIELDS)})",
                      file=sys.stderr)
        file = e.get("file")
        if file and not os.path.isfile(file):
            ok = False
            print(f"::error::quarantine entry {name}: file does not exist — "
                  f"remove the entry (fix landed) or fix the path",
                  file=sys.stderr)
        elif file and not file_has_tag(file, "integration"):
            ok = False
            print(f"::error::quarantine entry {name}: file is not tagged "
                  f"'integration' — the quarantine only shields the "
                  f"integration gate legs", file=sys.stderr)
        runs = e.get("runs") or []
        if runs and len({str(r) for r in runs}) < 2:
            ok = False
            print(f"::error::quarantine entry {name}: 'runs' must carry the "
                  f">=2 distinct proving gate runs (gh-1199 AC6/E3)",
                  file=sys.stderr)
    print(f"Quarantine list OK: {len(entries)} entr(ies), all documented")
    return 0 if ok else 1


def main() -> int:
    argv = sys.argv[1:]
    if argv == ["--check"]:
        return check()
    list_path = LIST_PATH
    if "--list" in argv:
        i = argv.index("--list")
        try:
            list_path = argv[i + 1]
        except IndexError:
            print("ERROR: --list needs a value", file=sys.stderr)
            return 2
        del argv[i:i + 2]
    try:
        entries = load_quarantine(list_path)
    except (OSError, json.JSONDecodeError, ValueError) as e:
        print(f"::error::{e}", file=sys.stderr)
        return 1

